// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MY_BANK} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MY_BANK c;

    function setUp() public {
        c = new MY_BANK(address(this));
    }

    function _run(uint256 unlockTime, uint256 value) internal {
        value = bound(value, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= value);
        bool reverted;
        try c.Put{value: value}(unlockTime) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted == false);
    }

    function testFuzz_run(uint256 unlockTime, uint256 value) public {
        _run(unlockTime, value);
    }

    receive() external payable { }
}
